import re
from typing import List, Dict, Any
from services.api.app.models.test_suite import TestCase

class PlaywrightCodeGenerator:
    @staticmethod
    def generate_typescript(project_name: str, test_cases: List[TestCase], base_url: str = "http://localhost:3000") -> str:
        clean_name = re.sub(r'[^a-zA-Z0-9_\- ]', '', project_name)
        lines = [
            "// Auto-generated by AI QA Agent Automation Lab",
            "// Execution verified against sandboxed Playwright runtime",
            "import { test, expect } from '@playwright/test';",
            "",
            f"test.describe('{clean_name} Automated Test Suite', () => {{",
        ]

        for tc in test_cases:
            spec = tc.latest_spec or {}
            steps = spec.get("steps", [])
            safe_title = tc.title.replace("'", "\\'")
            lines.append(f"  test('{tc.code_identifier}: {safe_title}', async ({{ page }}) => {{")

            for s in steps:
                action = s.get("action_type", "goto").lower()
                locator = s.get("target_locator", "")
                val = s.get("input_value", "")
                step_num = s.get("step_number", 1)

                lines.append(f"    // Step {step_num}: {action} {locator or ''}")
                if action == "goto":
                    url = locator or base_url
                    lines.append(f"    await page.goto('{url}');")
                elif action == "click":
                    if locator.startswith("getBy"):
                        lines.append(f"    await page.{locator}.click();")
                    else:
                        lines.append(f"    await page.locator('{locator}').click();")
                elif action in ["fill", "type"]:
                    safe_val = val.replace("'", "\\'")
                    if locator.startswith("getBy"):
                        lines.append(f"    await page.{locator}.fill('{safe_val}');")
                    else:
                        lines.append(f"    await page.locator('{locator}').fill('{safe_val}');")
                elif action in ["assert_visible", "assert"]:
                    if locator.startswith("getBy"):
                        lines.append(f"    await expect(page.{locator}).toBeVisible();")
                    else:
                        lines.append(f"    await expect(page.locator('{locator}')).toBeVisible();")
                elif action == "assert_text":
                    safe_exp = s.get("expected_result", "").replace("'", "\\'")
                    lines.append(f"    await expect(page.locator('{locator}')).toContainText('{safe_exp}');")
                else:
                    lines.append(f"    // Custom action: {action}")

            lines.append("  });")
            lines.append("")

        lines.append("});")
        return "\n".join(lines)
